// notices.ts — classification of the transcript's system notices. ONLY
// messages the server marked `synthetic: true` get classified (assistant
// entries with message.model="<synthetic>", generated by the Claude Code
// harness, never by the model or the user) — the gate is the JSONL field,
// not a text match over prose, so user content can never land here. The
// patterns below are the ones VERIFIED against the real corpus
// (~/.claude/projects):
//   · "You've hit your session limit · resets 10:20pm (Europe/Berlin)" (~125)
//   · "You've reached your <model> limit. Run /usage-credits…" (41)
//   · "API Error: 529 Overloaded…" / "API Error: 500…" / "Server error
//     mid-response" (26)
//   · "Prompt is too long" (63)
//   · "Your organization has disabled Claude subscription access…" (2)
//   · "No response requested." (117)
// Any other synthetic text falls back to the generic neutral ("system"): it's
// still a harness notice (a calm band), never assigned an invented severity.
// Severity carries NO terracotta — orange is for action/live; amber =
// limits/waiting, red = error (the same scale as the context gauge).
export type NoticeSeverity = 'neutral' | 'amber' | 'red'

export interface Notice {
  severity: NoticeSeverity
  label: string // the band's mono uppercase tag ("limit", "api error"…)
  body: string // the notice's text, without the highlighted part
  resets?: string // rate limit: the reset moment, highlighted separately
}

const RE_SESSION_LIMIT = /^You've hit your session limit\s*(?:·\s*resets\s+(.+))?$/
const RE_MODEL_LIMIT = /^You've reached your .+ limit\./
const RE_API_ERROR = /^API Error:/
const RE_PROMPT_LONG = /^Prompt is too long/
const RE_ORG_DISABLED = /disabled Claude subscription access/

export function classifyNotice(text: string): Notice {
  const s = text.trim()
  const limit = s.match(RE_SESSION_LIMIT)
  if (limit) {
    return {
      severity: 'amber',
      label: 'limit',
      body: "You've hit your session limit",
      ...(limit[1] ? { resets: `resets ${limit[1]}` } : {}),
    }
  }
  if (RE_MODEL_LIMIT.test(s)) return { severity: 'amber', label: 'limit', body: s }
  if (RE_API_ERROR.test(s)) return { severity: 'red', label: 'api error', body: s }
  if (RE_PROMPT_LONG.test(s)) return { severity: 'red', label: 'error', body: s }
  if (RE_ORG_DISABLED.test(s)) return { severity: 'amber', label: 'account', body: s }
  return { severity: 'neutral', label: 'system', body: s }
}
